//! Recompiled routines: Rust versions of the program's seg000 routines
//! (generated by `crates/lift` into `crates/dune-rec`), called in place of the
//! original when the CPU reaches their entry.
//!
//! A routine runs on the same machine state as the interpreter: registers in
//! [`crate::Cpu`], memory in [`crate::Hardware`], return addresses on the
//! emulated stack. It returns `Ok` after its `RET`, with CS:IP set to where
//! that `RET` went. When it meets something it does not handle natively it
//! returns [`Bail`]; the state is then at an instruction boundary and the
//! interpreter simply carries on from CS:IP. Bailing is always safe.
//!
//! Modes ([`RecMode`]):
//! - `On`: routines replace the original. Interrupts are not delivered while
//!   one runs; code that needs devices to progress (an `INT`, a far call into
//!   a driver) makes the routine bail so the run loop handles it.
//!   After a bail the interpreter runs until it reaches any block leader of a
//!   routine, where Rust takes over again.
//! - `Shadow`: the original runs as usual (interrupts, devices, nested
//!   routines). For the first [`Rec::samples`] calls of each routine the entry
//!   state is kept, and everything the program receives from outside the CPU
//!   is recorded ([`crate::hw::IoLog`]: port reads, hardware interrupts with
//!   the instruction they came before, BIOS/DOS results). When the original
//!   returns, the Rust version is replayed from the entry state, fed from
//!   that log, and registers, flags and all memory are compared; a replay
//!   that does different I/O is a difference too. The original's result is
//!   what the game continues with. In a replay, a call whose callee bails
//!   (an interrupt due inside it, a wait for one) finishes the callee
//!   there, interpreting with the recorded interrupts and resuming Rust at
//!   block leaders, and then goes on in the caller's Rust code: a routine
//!   that calls a waiting one is still checked to its end.
//!
//! Code spaces: seg000 (0), and the drivers the game loads (lifted from
//! their segments: [`Rec::with_driver`], 1, 2, ...), whose segments are read
//! from the game's driver tables. Statistics and counts are keyed by
//! [`key`]: the offset, plus 10000h times the space.

use std::collections::BTreeMap;

use cpu::{CS, Cpu, SP, SS, Step};

use crate::{GAME_DS, LOAD_SEG, Machine, hw::IoEvent};

/// Key of a routine in [`Rec::stats`] and [`Rec::returned`]: its offset,
/// plus 10000h times its code space.
pub fn key(space: u8, off: u16) -> u32 {
    (space as u32) << 16 | off as u32
}

/// The routine stopped early; continue interpreting from the current CS:IP.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Bail;

/// A recompiled routine, started at `pc`: its entry, or (resuming after a
/// bail) any of its block leaders. Started at the entry, the return address
/// is on the stack.
pub type Routine = fn(&mut Machine, u16) -> Result<(), Bail>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RecMode {
    On,
    Shadow,
}

/// Per-routine results of shadow checking.
#[derive(Debug, Default, Clone)]
pub struct ShadowStats {
    /// Calls compared and equal.
    pub ok: u32,
    /// Calls compared and different (first difference in `first_diff`).
    pub diff: u32,
    /// Equal, but Rust bailed somewhere (e.g. for an interrupt inside a
    /// block) and the interpreter ran part of the call.
    pub bailed: u32,
    /// Not compared: the call ran too long.
    pub skipped: u32,
    pub first_diff: Option<String>,
}

pub struct Rec {
    pub mode: RecMode,
    /// Routine by seg000 offset of its entry.
    pub table: Vec<Option<Routine>>,
    /// Routine to resume in, by seg000 offset of any of its block leaders
    /// (entries included): after a bail, Rust takes over again at the next
    /// leader the interpreter reaches.
    pub resume: Vec<Option<Routine>>,
    /// Per seg000 routine entry: the flags (CF..OF bits) its callers read
    /// after it returns; the shadow check ignores the others in the
    /// result (all by default; `with_flags_read`).
    pub flags_read: Vec<u16>,
    /// Shadow mode: calls checked per routine.
    /// seg000's generated code by block start: where a hand port gives up
    /// twice with nothing changed (a case it does not handle), the build
    /// without the interpreter goes on in it.
    generated: Vec<Option<Routine>>,
    fell_back: Option<(u16, u16, u64, u64, u64, u64)>,
    pub samples: u32,
    /// Running Rust one block at a time: 1 in the first block, 2 after, 3
    /// once it stopped at the next.
    one_block: u8,
    /// Shadow checks start at this virtual time (ns).
    pub check_from: u64,
    pub stats: BTreeMap<u32, ShadowStats>,
    /// `On` mode: entries into Rust (calls and resumptions), and bails.
    pub calls: u64,
    pub bails: u64,
    /// `On` mode profile: bails by the seg000 offset they left at, and
    /// instructions generated code ran through the interpreter, by opcode.
    pub bail_at: Vec<u64>,
    /// Per routine entry: calls of its Rust code that returned without
    /// bailing (so all of it ran in Rust).
    pub returned: Vec<u32>,
    pub stepped_op: Vec<u64>,
    /// Instructions the run loop interpreted, by code segment (the rest of
    /// the count ran in Rust, or in [`Machine::rec_interp`], also counted
    /// here under `--rec on`).
    pub interp_seg: Vec<u64>,
    /// The same by instruction address (CS, IP) (diagnostics).
    pub interp_at: std::collections::HashMap<(u16, u16), u64>,
    /// `--rec on`: where lifted code had no block to go on from after Rust
    /// ran (a port stopped there, or a bail mid-block), so the interpreter
    /// ran from there: block starts for the next lift (`dune-lift
    /// --leaders`).
    pub missed: std::collections::HashMap<(u16, u16), u64>,
    in_interp: bool,
    /// Shadow replays: instructions run by Rust and by the interpreter.
    pub replay_native: u64,
    pub replay_interp: u64,
    /// While a routine runs from shadow checking: nested code it cannot run
    /// natively is interpreted to completion instead of bailing.
    pub(crate) interp_nested: bool,
    /// The lifted drivers (code spaces 1, 2, ...).
    drivers: Vec<Driver>,
    /// Bails absorbed by [`Machine::finish_call`] during the current
    /// shadow replay (the call then counts as bailed: part of it was
    /// interpreted).
    nested_bails: u32,
    /// Shadow replays: a readable port's stretch run through an interrupt
    /// due inside it, waiting for the next boundary (see
    /// [`Machine::rec_stretch`]).
    defer: Option<Deferred>,
    /// Shadow replays: stretches run through an interrupt, and how many of
    /// them had to end in a bail (the interrupt changed what the rest of
    /// the stretch computed).
    pub deferred: u64,
    pub deferred_bailed: u64,
    /// Shadow replays whose result differed only with stretches run through
    /// interrupts, and were equal when replayed bailing at them instead.
    pub deferred_retried: u64,
    /// Bail at interrupts again (the second replay of such a call).
    no_through: bool,
    busy: bool,
    /// Shadow mode: calls in progress, innermost last.
    pending: Vec<Pending>,
    /// After a bail: the state it left (CS, IP, instruction count, idle
    /// time, next device event, run deadline). While all are unchanged, Rust
    /// must not take over there again (it would bail again): the
    /// interpreter runs one instruction.
    skip: Option<(u16, u16, u64, u64, u64, u64)>,
    /// The state the last bail left (see `skip`).
    last_bail: Option<(u16, u16, u64, u64, u64, u64)>,
    /// Instructions of the BIOS stubs and `INT`s run by
    /// [`Machine::host_step`] (diagnostics).
    pub host_steps: u64,
    /// `--rec native`: device events, interrupts and the run's deadline are
    /// taken at the first block boundary at or after they fall due, instead
    /// of the interpreter running up to their exact instruction. The game
    /// then runs without the interpreter wherever its code is lifted; its
    /// timing is as valid (interrupts are asynchronous) but no longer the
    /// interpreter's to the instruction.
    pub late_events: bool,
}

/// A shadow check waiting for the original to return.
struct Pending {
    /// [`key`] of the routine.
    entry: u32,
    f: Routine,
    cpu: Cpu,
    mem: Vec<u8>,
    /// The stack pointer at entry (above the return address once left).
    ss: u16,
    sp: u16,
    /// First event of this call in [`crate::hw::IoLog::events`].
    log_start: usize,
    /// Instruction count at entry.
    cpu_instructions: u64,
}

/// A lifted driver ([`Rec::with_driver`]).
struct Driver {
    name: &'static str,
    /// Routines and block leaders by offset in its segment.
    table: Vec<Option<Routine>>,
    resume: Vec<Option<Routine>>,
    /// `DS:` offset of the word holding its segment.
    seg_at: usize,
    /// The code it was lifted from (ranges, hash), and the virtual time of
    /// the next check of the driver in memory against it.
    code: (&'static [(u16, u16)], u64),
    next_check: u64,
    /// Time between checks: short right after the game loads it (its code
    /// may still be on its way in), doubling up to 100 ms.
    interval: u64,
    /// The segment the game's table held at the last check.
    seen_seg: u16,
    /// When a call into it last forced a check.
    forced_at: u64,
    /// The segment it was last found at with exactly that code (0: not
    /// loaded, or not the lifted one): only there it runs natively.
    ok_seg: u16,
    /// Whether it was ever found to be the lifted one, and the hashes of
    /// the other forms of its code seen since (see `REC_DRIVER_FORMS`).
    was_ok: bool,
    forms: Vec<u64>,
}

/// A stretch started at `cpu` (its first instruction) with a recorded
/// interrupt due inside it, run by Rust without it.
struct Deferred {
    cpu: Cpu,
    mem: Vec<u8>,
    log: Option<(usize, usize)>,
}

/// seg000's code, physical, and the byte the program patches itself
/// (the immediate of `mov ax, 25h` at C13B).
const CODE_START: usize = (LOAD_SEG as usize) << 4;
const CODE_END: usize = CODE_START + 0xf4b0;
const PATCHED: usize = CODE_START + 0xc13c;
/// seg000 offsets the listing declares as data (`db`/`dw`/`dd`) that the
/// program writes: data at 00A8h-00AFh, the circle's span handler at 64EDh,
/// a blit segment at CC94h, the PIT counter at E8D4h, the saved interrupt
/// vectors at E956h-E979h.
const DATA_IN_CODE: [std::ops::Range<u16>; 5] = [0x00a8..0x00b0, 0x64ed..0x64ef, 0xcc94..0xcc96, 0xe8d4..0xe8d5, 0xe956..0xe97a];

/// Driver code checks: at most and at least this far apart (virtual ns).
const CHECK_MIN_NS: u64 = 1_000_000;
const CHECK_MAX_NS: u64 = 100_000_000;

/// Pending checks kept at most (each holds a copy of memory).
const MAX_PENDING: usize = 32;

/// Instructions the interpreter may spend finishing one routine; also the
/// longest call that is checked (`REC_BUDGET=N` raises it, for videos and
/// scenes that run for seconds).
fn budget() -> u64 {
    static B: std::sync::OnceLock<u64> = std::sync::OnceLock::new();
    *B.get_or_init(|| std::env::var("REC_BUDGET").ok().and_then(|v| v.parse().ok()).unwrap_or(50_000_000))
}

/// `--rec on`: instructions an `INT` or far call may take on the
/// interpreter before the routine leaves it to the run loop.
const ON_INTERP_BUDGET: u32 = 20_000;

/// Recorded events kept at most; past this, pending checks are dropped
/// (`REC_EVENTS=N` raises it, with `REC_BUDGET`).
fn max_events() -> usize {
    static E: std::sync::OnceLock<usize> = std::sync::OnceLock::new();
    *E.get_or_init(|| std::env::var("REC_EVENTS").ok().and_then(|v| v.parse().ok()).unwrap_or(1 << 21))
}

/// `REC_ONLY=hex,...`: shadow-check only calls of these seg000 entries
/// (the long ones then have the pending slots and the time to themselves).
fn check_only(k: u32) -> bool {
    static O: std::sync::OnceLock<Option<Vec<u32>>> = std::sync::OnceLock::new();
    O.get_or_init(|| {
        std::env::var("REC_ONLY").ok().map(|v| v.split(',').filter_map(|e| u32::from_str_radix(e.trim(), 16).ok()).collect())
    })
    .as_ref()
    .is_none_or(|o| o.contains(&k))
}

impl Rec {
    /// The flags each routine's callers read (from `flags_used.py`):
    /// (entry, mask) for those that read fewer than all.
    pub fn with_flags_read(mut self, table: &[(u16, u16)]) -> Rec {
        for &(e, m) in table {
            self.flags_read[e as usize] = m | !FLAG_BITS;
        }
        self
    }

    pub fn new(mode: RecMode, routines: &[(u16, Routine)], leaders: &[(u16, Routine)]) -> Rec {
        let mut table = vec![None; 0x10000];
        let mut resume = vec![None; 0x10000];
        for &(off, f) in leaders {
            resume[off as usize] = Some(f);
        }
        // The generated code at each block start, before the hand ports
        // take over their entries (see `generated`).
        let generated = resume.clone();
        for &(off, f) in routines {
            table[off as usize] = Some(f);
            resume[off as usize] = Some(f);
        }
        Rec {
            mode,
            table,
            resume,
            flags_read: vec![0xffff; 0x10000],
            generated,
            fell_back: None,
            samples: 20,
            check_from: 0,
            one_block: 0,
            stats: BTreeMap::new(),
            calls: 0,
            bails: 0,
            bail_at: vec![0; 0x10000],
            returned: vec![0; 0x40000],
            stepped_op: vec![0; 256],
            interp_seg: vec![0; 0x10000],
            interp_at: std::collections::HashMap::new(),
            missed: std::collections::HashMap::new(),
            in_interp: false,
            replay_native: 0,
            replay_interp: 0,
            interp_nested: false,
            drivers: Vec::new(),
            nested_bails: 0,
            defer: None,
            deferred: 0,
            deferred_bailed: 0,
            deferred_retried: 0,
            no_through: false,
            busy: false,
            skip: None,
            last_bail: None,
            host_steps: 0,
            late_events: false,
            pending: Vec::new(),
        }
    }

    /// Add a lifted driver (the next code space): its routines and block
    /// leaders by offset, and the `DS:` offset of the word where the game
    /// keeps its segment (its table's first far pointer's segment).
    ///
    /// `code`: the bytes the driver was lifted from (ranges, FNV-1a hash).
    /// Every 100 ms of virtual time the driver in memory is checked against
    /// them; while it differs (not loaded yet, another driver, or code it
    /// rewrote that the lifter did not see change), it is interpreted.
    pub fn with_driver(
        mut self,
        name: &'static str,
        routines: &[(u16, Routine)],
        leaders: &[(u16, Routine)],
        seg_at: u16,
        code: (&'static [(u16, u16)], u64),
    ) -> Rec {
        if routines.is_empty() || self.drivers.len() == 3 {
            return self;
        }
        let mut table = vec![None; 0x10000];
        let mut resume = vec![None; 0x10000];
        for &(off, f) in leaders {
            resume[off as usize] = Some(f);
        }
        for &(off, f) in routines {
            table[off as usize] = Some(f);
            resume[off as usize] = Some(f);
        }
        self.drivers.push(Driver { name, table, resume, seg_at: seg_at as usize, code, next_check: 0, interval: CHECK_MIN_NS, seen_seg: 0, forced_at: 0, ok_seg: 0, was_ok: false, forms: Vec::new() });
        self
    }
}

impl Rec {
    /// Count `n` instructions the interpreter ran at CS:IP.
    pub(crate) fn count_interp(&mut self, cs: u16, ip: u16, n: u64) {
        self.interp_seg[cs as usize] += n;
        *self.interp_at.entry((cs, ip)).or_default() += n;
        self.in_interp = true;
    }
}

impl Machine {
    /// On device events: check each lifted driver in memory against the code
    /// it was lifted from (see [`Rec::with_driver`]).
    pub(crate) fn rec_driver_check(&mut self, now: u64) {
        let Some(rec) = &self.rec else { return };
        for i in 0..rec.drivers.len() {
            let d = &self.rec.as_ref().unwrap().drivers[i];
            let a = GAME_DS as usize * 16 + d.seg_at;
            let seg = u16::from_le_bytes([self.hw.mem[a], self.hw.mem[a + 1]]);
            if now < d.next_check && seg == d.seen_seg {
                continue;
            }
            let ok = self.driver_hash(i, &self.hw.mem) == Some(d.code.1);
            // The game's pointer moved (or was cleared) while the code is
            // still where it was verified: it stays there, natively (its
            // interrupt handlers keep running from there).
            let kept = !ok && d.ok_seg != 0 && d.ok_seg != seg && self.driver_hash_at(i, &self.hw.mem, d.ok_seg) == Some(d.code.1);
            let d = &mut self.rec.as_mut().unwrap().drivers[i];
            if seg != d.seen_seg {
                d.interval = CHECK_MIN_NS;
            }
            d.seen_seg = seg;
            d.interval = if ok { CHECK_MAX_NS } else { (d.interval * 2).min(CHECK_MAX_NS) };
            d.next_check = now + d.interval;
            // Its code changed where it was (a pointer to it overwritten is
            // not news).
            if d.ok_seg != 0 && d.ok_seg == seg && !ok {
                eprintln!("rec: the {} driver at {seg:04x} is not the one lifted (code hash differs) at {:.3}s: interpreting it", d.name, now as f64 / 1e9);
            }
            // The lifted driver's code rewritten into a form the lift has not
            // seen: dump it, for the next lift's `--also` images.
            if ok {
                d.was_ok = true;
            } else if d.was_ok && seg != 0 && !kept && d.forms.len() < 64 {
                let base = (seg as usize) << 4;
                if base + 0x10000 <= self.hw.mem.len() {
                    let h = {
                        let mut h = 0xcbf2_9ce4_8422_2325u64;
                        for &(s, e) in d.code.0 {
                            for &b in &self.hw.mem[base + s as usize..base + e as usize] {
                                h = (h ^ b as u64).wrapping_mul(0x100_0000_01b3);
                            }
                        }
                        h
                    };
                    if !d.forms.contains(&h) {
                        d.forms.push(h);
                        if let Some(dir) = std::env::var_os("REC_DRIVER_FORMS") {
                            let dir = std::path::PathBuf::from(dir).join(format!("{}-{h:016x}", d.name));
                            let _ = std::fs::create_dir_all(&dir);
                            let _ = std::fs::write(dir.join(format!("{}.bin", d.name)), &self.hw.mem[base..base + 0x10000]);
                        }
                    }
                }
            }
            d.ok_seg = if ok {
                seg
            } else if kept {
                d.ok_seg
            } else {
                0
            };
            if kept {
                d.next_check = now + CHECK_MIN_NS.max(d.interval);
            }
        }
    }

    /// A far call into segment `seg`: if a driver the game keeps there is
    /// not (yet) found to be the lifted one, check it now (at most once a
    /// millisecond), so it runs natively from its first calls on.
    fn rec_driver_called(&mut self, seg: u16) {
        let now = self.now_ns();
        let Some(rec) = &mut self.rec else { return };
        let mut due = false;
        for d in &mut rec.drivers {
            let a = GAME_DS as usize * 16 + d.seg_at;
            let at = u16::from_le_bytes([self.hw.mem[a], self.hw.mem[a + 1]]);
            if at == seg && d.ok_seg != seg && now >= d.forced_at + CHECK_MIN_NS {
                d.forced_at = now;
                d.next_check = 0;
                due = true;
            }
        }
        if due {
            self.rec_driver_check(now);
        }
    }

    /// Diagnostics: each lifted driver's name, the segment the game's
    /// table holds, where its code was last verified (0: nowhere), and
    /// whether the code at the table's segment is the lifted one now.
    pub fn rec_drivers(&self) -> Vec<(&'static str, u16, u16, bool)> {
        let Some(rec) = &self.rec else { return Vec::new() };
        (0..rec.drivers.len())
            .map(|i| {
                let d = &rec.drivers[i];
                let a = GAME_DS as usize * 16 + d.seg_at;
                let seg = u16::from_le_bytes([self.hw.mem[a], self.hw.mem[a + 1]]);
                (d.name, seg, d.ok_seg, self.driver_hash(i, &self.hw.mem) == Some(d.code.1))
            })
            .collect()
    }

    /// Driver `i`'s code bytes in `mem` hashed as the lifter did (None
    /// before it is loaded).
    fn driver_hash(&self, i: usize, mem: &[u8]) -> Option<u64> {
        let d = &self.rec.as_ref()?.drivers[i];
        let a = GAME_DS as usize * 16 + d.seg_at;
        self.driver_hash_at(i, mem, u16::from_le_bytes([mem[a], mem[a + 1]]))
    }

    /// Driver `i`'s code bytes hashed as if it were at segment `seg`.
    fn driver_hash_at(&self, i: usize, mem: &[u8], seg: u16) -> Option<u64> {
        let d = &self.rec.as_ref()?.drivers[i];
        if seg == 0 {
            return None;
        }
        let base = (seg as usize) << 4;
        let mut h = 0xcbf2_9ce4_8422_2325u64;
        for &(s, e) in d.code.0 {
            for &b in &mem[base + s as usize..base + e as usize] {
                h = (h ^ b as u64).wrapping_mul(0x100_0000_01b3);
            }
        }
        Some(h)
    }

    /// Whether a lifted driver is loaded in `mem` with other code than it
    /// was lifted from.
    fn drivers_foreign(&self, mem: &[u8]) -> bool {
        let Some(rec) = &self.rec else { return false };
        (0..rec.drivers.len()).any(|i| self.driver_hash(i, mem).is_some_and(|h| h != rec.drivers[i].code.1))
    }

    /// Whether any lifted driver's code differs between two memories.
    fn drivers_changed(&self, a: &[u8], b: &[u8]) -> bool {
        let n = self.rec.as_ref().map_or(0, |r| r.drivers.len());
        (0..n).any(|i| self.driver_hash(i, a) != self.driver_hash(i, b))
    }

    /// The code space of segment `cs`: 0 for seg000, 1.. for a lifted
    /// driver's segment.
    #[inline]
    fn rec_space(&self, cs: u16) -> Option<u8> {
        if cs == LOAD_SEG {
            return Some(0);
        }
        let rec = self.rec.as_ref()?;
        // Where its code was last verified (see `rec_driver_check`).
        let i = rec.drivers.iter().position(|d| d.ok_seg != 0 && d.ok_seg == cs)?;
        Some(i as u8 + 1)
    }

    /// The routine with its entry at CS:`ip` (`entry`), or any routine with a
    /// block leader there.
    #[inline]
    fn rec_routine(&self, cs: u16, ip: u16, entry: bool) -> Option<Routine> {
        let space = self.rec_space(cs)?;
        let r = self.rec.as_ref()?;
        let t = match (space, entry) {
            (0, true) => &r.table,
            (0, false) => &r.resume,
            (k, true) => &r.drivers[k as usize - 1].table,
            (k, false) => &r.drivers[k as usize - 1].resume,
        };
        t[ip as usize]
    }

    /// Run-loop hook: called before each instruction when `rec` is set.
    /// Returns true if it changed the state (the loop must re-check).
    pub(crate) fn rec_hook(&mut self) -> bool {
        let (cs, ip) = (self.cpu.sregs[CS], self.cpu.ip);
        let Some(space) = self.rec_space(cs) else { return false };
        let Some(rec) = &mut self.rec else { return false };
        if rec.busy {
            return false;
        }
        let state = (cs, ip, self.cpu.instructions, self.idle_ns, self.next_event, self.run_deadline);
        let skipping = rec.skip.take() == Some(state);
        // (Once per place and state: if the generated code makes no
        // progress either, there is nothing else to run.)
        if skipping && (cfg!(feature = "interp") || rec.mode != RecMode::On || space != 0 || rec.fell_back.replace(state) == Some(state)) {
            return false;
        }
        match rec.mode {
            RecMode::On => {
                // A breakpoint (harnesses) must stop at its exact instruction,
                // which Rust code would run through: interpret meanwhile, or
                // without the interpreter, run Rust one block at a time (the
                // run loop checks the breakpoint between them).
                let one_block = self.break_at.is_some();
                if one_block && cfg!(feature = "interp") {
                    return false;
                }
                // The graphics recorder watches the driver's entries and
                // returns instruction by instruction.
                if space > 0 && self.gfx.active() && self.rec.as_ref().unwrap().drivers[space as usize - 1].name == "graphics" {
                    return false;
                }
                // Without the interpreter: a hand port that gave up here
                // twice leaves it to the generated code.
                if skipping {
                    let rec = self.rec.as_ref().unwrap();
                    match (rec.generated[ip as usize], rec.resume[ip as usize]) {
                        (Some(g), Some(h)) if g as usize != h as usize => {}
                        _ => return false,
                    }
                }
                let found = if skipping { self.rec.as_ref().unwrap().generated[ip as usize] } else { self.rec_routine(cs, ip, false) };
                let Some(f) = found else {
                    let rec = self.rec.as_mut().unwrap();
                    if !rec.in_interp {
                        *rec.missed.entry((cs, ip)).or_default() += 1;
                    }
                    return false;
                };
                let rec = self.rec.as_mut().unwrap();
                rec.in_interp = false;
                rec.calls += 1;
                rec.busy = true;
                rec.one_block = if one_block { 1 } else { 0 };
                let r = f(self, ip);
                let rec = self.rec.as_mut().unwrap();
                rec.busy = false;
                let planned = rec.one_block == 3;
                let mut traced = false;
                rec.one_block = 0;
                if r.is_err() {
                    rec.bails += 1;
                    // A port may stop where the generated code goes on: Rust
                    // tries once more there; a second bail with nothing
                    // changed leaves one instruction to the interpreter.
                    let at = (self.cpu.sregs[CS], self.cpu.ip, self.cpu.instructions, self.idle_ns, self.next_event, self.run_deadline);
                    // (Not the planned stops of one block at a time.)
                    if !planned && rec.last_bail.replace(at) == Some(at) {
                        rec.skip = Some(at);
                        traced = std::env::var_os("REC_TRACE_SKIP").is_some();
                    }
                    if self.cpu.sregs[CS] == LOAD_SEG && !one_block {
                        rec.bail_at[self.cpu.ip as usize] += 1;
                    }
                }
                if traced {
                    eprintln!(
                        "rec skip at {cs:04x}:{:04x}: now {} next_event {} deadline {} reschedule {} IF {} irq_pending {} inhibit {} halted {}",
                        self.cpu.ip,
                        self.now_ns(),
                        self.next_event,
                        self.run_deadline,
                        self.hw.reschedule,
                        self.cpu.flag(cpu::IF),
                        self.hw.irq_pending(),
                        self.cpu.irq_inhibit,
                        self.cpu.halted
                    );
                }
                true
            }
            RecMode::Shadow => {
                let Some(f) = self.rec_routine(cs, ip, true) else { return false };
                let k = key(space, ip);
                let early = self.now_ns() < self.rec.as_ref().unwrap().check_from;
                let rec = self.rec.as_mut().unwrap();
                let st = rec.stats.entry(k).or_default();
                let checked = st.ok + st.diff + st.bailed + st.skipped;
                let in_flight = rec.pending.iter().filter(|p| p.entry == k).count() as u32;
                let room = !early && checked + in_flight < rec.samples && rec.pending.len() < MAX_PENDING && check_only(k);
                let (ss, sp) = (self.cpu.sregs[SS], self.cpu.regs[SP]);
                let ret = self.mem_read16(ss, sp);
                let ret_cs = self.mem_read16(ss, sp.wrapping_add(2));
                // Only real calls: an entry reached by a jump or by falling
                // through has no return address on the stack. The driver is
                // also entered by far calls from seg000.
                let called = self.called_from(cs, ret, ip) || (space > 0 && ret_cs == LOAD_SEG && self.called_far(ret_cs, ret));
                if room && called {
                    self.push_check(k, f);
                }
                false
            }
        }
    }

    fn push_check(&mut self, entry: u32, f: Routine) {
        let p = Pending {
            entry,
            f,
            cpu: self.cpu.clone(),
            mem: self.hw.mem.clone(),
            ss: self.cpu.sregs[SS],
            sp: self.cpu.regs[SP],
            log_start: self.hw.io_log.events.len(),
            cpu_instructions: self.cpu.instructions,
        };
        self.rec.as_mut().unwrap().pending.push(p);
        self.hw.io_log.recording = true;
    }

    /// Shadow mode, for harnesses that call a routine themselves: check the
    /// call starting now (CS:IP at a routine's entry, the return address
    /// pushed), whatever the sample count. False if there is no routine here.
    pub fn rec_check_here(&mut self) -> bool {
        let ip = self.cpu.ip;
        let f = match &self.rec {
            Some(r) if r.mode == RecMode::Shadow && self.cpu.sregs[CS] == LOAD_SEG => r.table[ip as usize],
            _ => None,
        };
        let Some(f) = f else { return false };
        self.push_check(ip as u32, f);
        true
    }

    /// Drop the checks in progress (before loading another state). Returns
    /// how many there were.
    pub fn rec_drop_checks(&mut self) -> usize {
        let Some(rec) = &mut self.rec else { return 0 };
        let n = rec.pending.len();
        rec.pending.clear();
        self.hw.io_log.recording = false;
        self.hw.io_log.events.clear();
        n
    }

    /// Whether the code in segment `cs` just before `ret` is a near call
    /// that can have gone to `target` (direct `CALL rel16` to it, or an
    /// indirect `CALL r/m16` of 2 to 4 bytes).
    fn called_from(&self, cs: u16, ret: u16, target: u16) -> bool {
        let at = |off: u16| self.hw.mem[(((cs as usize) << 4) + off as usize) & 0xf_ffff];
        if at(ret.wrapping_sub(3)) == 0xe8 {
            let rel = u16::from_le_bytes([at(ret.wrapping_sub(2)), at(ret.wrapping_sub(1))]);
            if ret.wrapping_add(rel) == target {
                return true;
            }
        }
        (2..=4).any(|n| {
            let modrm = at(ret.wrapping_sub(n - 1));
            at(ret.wrapping_sub(n)) == 0xff && (modrm >> 3) & 7 == 2 && modrm_len(modrm) == n - 1
        })
    }

    /// Whether the code at `cs` just before `ret` is a far call (`CALL
    /// ptr16:16`, or `CALL m16:16` of 2 to 4 bytes).
    fn called_far(&self, cs: u16, ret: u16) -> bool {
        let at = |off: u16| self.hw.mem[(((cs as usize) << 4) + off as usize) & 0xf_ffff];
        at(ret.wrapping_sub(5)) == 0x9a
            || (2..=4).any(|n| {
                let modrm = at(ret.wrapping_sub(n - 1));
                at(ret.wrapping_sub(n)) == 0xff && (modrm >> 3) & 7 == 3 && modrm_len(modrm) == n - 1
            })
    }

    /// Shadow mode, before each instruction: has the innermost pending call
    /// returned (or been abandoned)?
    pub(crate) fn rec_pending(&mut self) {
        let Some(rec) = &mut self.rec else { return };
        if rec.pending.is_empty() {
            return;
        }
        // Calls too long to check, or too many recorded events: drop the
        // oldest pending check.
        let first = &rec.pending[0];
        if self.cpu.instructions - first.cpu.instructions > budget() || self.hw.io_log.events.len() > max_events() {
            let p = rec.pending.remove(0);
            rec.stats.entry(p.entry).or_default().skipped += 1;
            let keep = rec.pending.first().map_or(self.hw.io_log.events.len(), |p| p.log_start);
            self.hw.io_log.events.drain(..keep);
            for p in &mut rec.pending {
                p.log_start -= keep;
            }
        }
        // The stack is above a call's entry frame: it returned to its caller,
        // or left it some other way (a routine that pops its own return
        // address, or ends in a jump chain dropping the frame). The replay
        // runs exactly as many instructions and must end in this same state.
        // Several calls can be left at once: all are checked at this point.
        loop {
            let rec = self.rec.as_mut().unwrap();
            let Some(p) = rec.pending.last() else { break };
            let c = &self.cpu;
            if c.sregs[SS] != p.ss || c.regs[SP] <= p.sp {
                break;
            }
            let p = rec.pending.pop().unwrap();
            self.shadow_replay(p);
        }
        let rec = self.rec.as_mut().unwrap();
        if rec.pending.is_empty() {
            self.hw.io_log.recording = false;
            self.hw.io_log.events.clear();
        }
    }

    /// Replay a routine's Rust version from its entry state, fed with what
    /// the original received (port reads, interrupts, BIOS/DOS results), and
    /// compare it with the original's result (the current state), which is
    /// then restored.
    fn shadow_replay(&mut self, p: Pending) {
        // A call that wrote into the code segment (other than the known
        // patch site) is marked in the report: if it changed code, the Rust
        // version, which keeps the code as it was, runs differently.
        // Data the program keeps in its code segment (read as data by Rust
        // too) does not count.
        let code = CODE_START..CODE_END;
        let code_at = p.mem[code.clone()]
            .iter()
            .zip(&self.hw.mem[code.clone()])
            .enumerate()
            .find(|&(i, (a, b))| a != b && CODE_START + i != PATCHED && !DATA_IN_CODE.iter().any(|r| r.contains(&(i as u16))))
            .map(|(i, _)| format!(" at {i:04x}"));
        let code_changed = code_at.is_some() || self.drivers_changed(&p.mem, &self.hw.mem);
        let code_at = code_at.unwrap_or_else(|| " (a driver)".into());
        let foreign = self.drivers_foreign(&p.mem);
        let entry_state = (p.cpu.clone(), p.mem.clone());
        let cpu1 = std::mem::replace(&mut self.cpu, p.cpu);
        let mem1 = std::mem::replace(&mut self.hw.mem, p.mem);
        let io1 = self.hw.io_count;
        let ints1 = self.int_counts;
        let end = self.hw.io_log.events.len();
        self.hw.io_log.recording = false;
        self.hw.io_log.replay = Some((p.log_start, end));
        self.hw.io_log.mismatch = None;
        self.hw.io_log.stop_at = cpu1.instructions;
        let rec = self.rec.as_mut().unwrap();
        rec.interp_nested = true;
        rec.busy = true;
        let mut retried = false;
        let (diff, bails) = loop {
            let deferred0 = self.rec.as_ref().unwrap().deferred;
            let (finished, bails) = self.replay_drive(p.entry, p.f);
            let unused = self.hw.io_log.peek().map(|e| crate::hw::describe(Some(e)));
            let mismatch = self.hw.io_log.mismatch.take().or_else(|| unused.map(|e| format!("io: original also had {e}")));
            let diff = match (mismatch, finished) {
                (Some(m), _) => Some(m),
                (None, false) => Some(format!(
                    "did not finish: at {:04x}:{:04x} after {} instructions, original {}",
                    self.cpu.sregs[CS],
                    self.cpu.ip,
                    self.cpu.instructions - p.cpu_instructions,
                    cpu1.instructions - p.cpu_instructions
                )),
                (None, true) => {
                    // Flags no caller reads: the original's, so they don't count.
                    let unread = match self.rec.as_ref() {
                        Some(r) if p.entry < 0x10000 => FLAG_BITS & !r.flags_read[p.entry as usize],
                        _ => 0,
                    };
                    let mut port = self.cpu.clone();
                    port.set_flags(port.flags() & !unread | cpu1.flags() & unread);
                    compare(&cpu1, &mem1, &port, &self.hw.mem)
                }
            };
            // A port may keep what it read across a stretch (right under
            // `--rec on`, where no interrupt comes while Rust runs); run
            // through an interrupt, that can be stale. Such a result is
            // checked again bailing at the interrupts, unless a stretch
            // itself was found different.
            let rec = self.rec.as_mut().unwrap();
            let through = rec.deferred > deferred0;
            let stretch_wrong = diff.as_deref().is_some_and(|d| d.starts_with("stretch from"));
            if diff.is_none() || !through || stretch_wrong || retried {
                rec.no_through = false;
                break (diff, bails + retried as u32);
            }
            retried = true;
            rec.no_through = true;
            rec.deferred_retried += 1;
            rec.defer = None;
            self.cpu = entry_state.0.clone();
            self.hw.mem.copy_from_slice(&entry_state.1);
            self.hw.io_log.replay = Some((p.log_start, end));
            self.hw.io_log.mismatch = None;
        };
        self.hw.io_log.replay = None;
        self.hw.io_log.recording = true;
        let entry_ns = self.now_at(p.cpu_instructions);
        let rec = self.rec.as_mut().unwrap();
        rec.interp_nested = false;
        rec.busy = false;
        let diff = diff.map(|d| if code_changed { format!("{d} (the call wrote into the code segment{code_at})") } else { d });
        let diff = diff.map(|d| if foreign { format!("{d} (a driver's code was not the lifted one at the call)") } else { d });
        let st = rec.stats.entry(p.entry).or_default();
        match &diff {
            Some(d) => {
                st.diff += 1;
                if st.first_diff.is_none() {
                    st.first_diff = Some(d.clone());
                }
                // REC_DIFF_LOG=1: every differing call, with the virtual
                // time and instruction count of its entry.
                static LOG: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
                if *LOG.get_or_init(|| std::env::var_os("REC_DIFF_LOG").is_some()) {
                    let t = entry_ns as f64 / 1e9;
                    eprintln!("rec diff: {t:.3}s insn {} entry {:x}: {d}", p.cpu_instructions, p.entry);
                }
            }
            None if bails > 0 => st.bailed += 1,
            None => st.ok += 1,
        }
        // Carry on from the original's result.
        self.cpu = cpu1;
        self.hw.mem = mem1;
        self.hw.io_count = io1;
        self.int_counts = ints1;
    }

    /// Shadow replay: run routine `f` from its entry for as many
    /// instructions as the original's call took (`IoLog::stop_at`), resuming
    /// in Rust at every block leader and interpreting only where Rust bailed.
    /// Returns (finished, bails).
    fn replay_drive(&mut self, entry: u32, f: Routine) -> (bool, u32) {
        let stop = self.hw.io_log.stop_at;
        let start = self.cpu.instructions;
        let interp0 = self.rec.as_ref().unwrap().replay_interp;
        self.rec.as_mut().unwrap().nested_bails = 0;
        self.hw.io_log.stopped = false;
        let r = f(self, entry as u16);
        let mut just_bailed = self.rec_settle().and(r).is_err();
        if !just_bailed {
            self.rec.as_mut().unwrap().returned[entry as usize] += 1;
        }
        let mut bails = (just_bailed && !self.hw.io_log.stopped) as u32;
        let finished = loop {
            if self.cpu.instructions >= stop {
                break self.cpu.instructions == stop;
            }
            if self.replay_irq() {
                just_bailed = false;
                continue;
            }
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > budget() {
                break false;
            }
            let ip = self.cpu.ip;
            let resume = if just_bailed { None } else { self.rec_routine(self.cpu.sregs[CS], ip, false) };
            if let Some(g) = resume {
                self.hw.io_log.stopped = false;
                let r = g(self, ip);
                just_bailed = self.rec_settle().and(r).is_err();
                bails += (just_bailed && !self.hw.io_log.stopped) as u32;
            } else {
                just_bailed = false;
                if self.step_insn().is_err() {
                    break false;
                }
            }
        };
        let rec = self.rec.as_mut().unwrap();
        let interp = rec.replay_interp - interp0;
        rec.replay_native += (self.cpu.instructions - start).saturating_sub(interp);
        (finished, bails + rec.nested_bails)
    }

    /// Replay: deliver the next recorded interrupt if it is due now (or the
    /// CPU is halted waiting for it). True if one was delivered.
    fn replay_irq(&mut self) -> bool {
        match self.hw.io_log.peek() {
            Some(&IoEvent::Irq { vector, at }) if at == self.cpu.instructions || self.cpu.halted => {
                self.hw.io_log.advance();
                self.cpu.interrupt(&mut self.hw, vector);
                true
            }
            Some(&IoEvent::Irq { at, .. }) if at < self.cpu.instructions => {
                let now = self.cpu.instructions;
                if std::env::var_os("REC_DEBUG").is_some() && self.hw.io_log.mismatch.is_none() {
                    eprintln!("irq missed at {:04x}:{:04x} (due {at}, now {now})", self.cpu.sregs[CS], self.cpu.ip);
                }
                self.hw.io_log.fail(format!("irq missed: due before instruction {at}, now {now}"));
                false
            }
            _ => false,
        }
    }

    /// Replay: a BIOS/DOS service the replay reached; apply the original's.
    pub(crate) fn replay_service(&mut self, n: u8) {
        let log = &mut self.hw.io_log;
        let ev = match log.peek() {
            Some(e @ IoEvent::Callback { n: k, .. }) if *k == n => {
                let e = e.clone();
                log.advance();
                e
            }
            other => {
                let what = crate::hw::describe(other);
                log.fail(format!("io: service int {n:02x}, original: {what}"));
                return;
            }
        };
        let IoEvent::Callback { before, after, writes, .. } = ev else { unreachable!() };
        if let Some(d) = compare_cpu(&before, &self.cpu) {
            self.hw.io_log.fail(format!("io: service int {n:02x} asked with different registers: {d}"));
            return;
        }
        let count = self.cpu.instructions;
        self.cpu = *after;
        self.cpu.instructions = count;
        for (a, v) in writes {
            self.hw.mem[a as usize] = v;
        }
    }

    /// For generated code, at the start of a block of `len` instructions:
    /// true when the routine must stop there (it bails).
    /// - Running (`--rec on`): an interrupt is pending, or a device event or
    ///   the run's deadline falls inside the block: the interpreter runs it,
    ///   so all of these happen at the same instruction as without `--rec`
    ///   (and a native loop polling a timer variable sees it change).
    /// - Shadow replay: a recorded interrupt, or the end of the original's
    ///   call, falls in this block; the interpreter gets there exactly.
    #[inline]
    pub fn rec_tick(&mut self, len: u32) -> bool {
        if self.hw.io_log.replay.is_some() {
            let end = self.cpu.instructions + len as u64;
            if self.hw.io_log.next_irq(len as usize + 1).is_some_and(|at| at < end) {
                return true;
            }
            self.hw.io_log.stopped = self.hw.io_log.stop_at < end;
            return self.hw.io_log.stopped;
        }
        if self.rec.as_ref().is_some_and(|r| r.interp_nested) {
            return false;
        }
        // One block per call (a breakpoint is set): stop at the next block.
        if let Some(r) = self.rec.as_mut()
            && r.one_block > 0
        {
            if r.one_block >= 2 {
                r.one_block = 3;
                return true;
            }
            r.one_block = 2;
        }
        // The run loop checks before every instruction; the block's last
        // instruction starts at this count. Time comes from the count, so a
        // device event or the run's deadline inside the block is known now.
        let late = self.rec.as_ref().is_some_and(|r| r.late_events);
        if late {
            // STI's one-instruction hold ends at the block boundary too, as
            // every other event's exact instruction does: a pending
            // interrupt is taken here (else only the interpreter could run
            // the one instruction before it).
            self.cpu.irq_inhibit = false;
        }
        let last = self.now_at(self.cpu.instructions + if late { 0 } else { len.max(1) as u64 - 1 });
        // An interrupt pending is taken before the block, or (right after
        // STI) after its first instruction: then the interpreter runs that.
        // Native timing: the run loop has updated the devices at this very
        // time before Rust runs; an event due again right now (a device
        // with more to do at once) waits for the block's end, as time must
        // pass for it (else Rust would bail here for ever).
        let due = (if late { last > self.next_event } else { last >= self.next_event })
            || last >= self.run_deadline
            || self.hw.reschedule
            || (self.cpu.flag(cpu::IF) && self.hw.irq_pending());
        if !due {
            // The block runs: STI's one-instruction hold ends with its first
            // instruction (the interpreter clears it at every step).
            self.cpu.irq_inhibit = false;
        }
        due
    }

    fn interp_until(&mut self, budget: u64, done: impl Fn(&Cpu) -> bool) -> Result<(), Bail> {
        for _ in 0..budget {
            if done(&self.cpu) {
                return Ok(());
            }
            if self.hw.io_log.replay.is_some() && self.cpu.instructions >= self.hw.io_log.stop_at {
                return Err(Bail);
            }
            self.step_insn()?;
        }
        Err(Bail)
    }

    /// Execute the instruction at CS:IP with the interpreter (BIOS/DOS
    /// services run, no interrupts). For generated code. During a shadow
    /// replay, a recorded interrupt due now is delivered instead.
    pub fn step_insn(&mut self) -> Result<(), Bail> {
        let replay = self.hw.io_log.replay.is_some();
        if replay && self.replay_irq() {
            return Ok(());
        }
        if replay {
            let n = self.cpu.instructions;
            let r = self.step_raw();
            let rec = self.rec.as_mut().unwrap();
            rec.replay_interp += self.cpu.instructions - n;
            return r;
        }
        if let Some(rec) = &mut self.rec
            && rec.mode == RecMode::On
        {
            // Skip prefixes: the opcode that needed the interpreter.
            let base = (self.cpu.sregs[CS] as usize) << 4;
            let mut off = self.cpu.ip;
            let mut op = self.hw.mem[(base + off as usize) & 0xf_ffff];
            while matches!(op, 0x26 | 0x2e | 0x36 | 0x3e | 0xf0 | 0xf2 | 0xf3) {
                off = off.wrapping_add(1);
                op = self.hw.mem[(base + off as usize) & 0xf_ffff];
            }
            rec.stepped_op[op as usize] += 1;
        }
        self.step_raw()
    }

    /// `--rec on`: the instruction at CS:IP if it is one the host runs
    /// without the interpreter: `INT nn` and the calls the program makes
    /// into code that is not inline (`CALL rel16`, `CALL ptr16:16`, `CALL
    /// [disp16]` near or far, with a segment prefix or not) anywhere, and
    /// the BIOS stubs' own instructions (`FE 38 nn` a service, `INT nn`,
    /// `IRET`; see `bios::install`). Exactly as the CPU would: the same
    /// instruction count, the same stack. None: the interpreter must run it.
    pub(crate) fn host_step(&mut self) -> Option<Step> {
        use cpu::{DS, ES};
        if !self.rec.as_ref().is_some_and(|r| r.mode == RecMode::On) || self.cpu.halted {
            return None;
        }
        let (cs, ip) = (self.cpu.sregs[CS], self.cpu.ip);
        let base = (cs as usize) << 4;
        let at = |o: u16| self.hw.mem[(base + ip.wrapping_add(o) as usize) & 0xf_ffff];
        let word = |o: u16| at(o) as u16 | (at(o + 1) as u16) << 8;
        let stub = cs == crate::STUB_SEG;
        let (seg, p) = match at(0) {
            0x26 => (ES, 1),
            0x2e => (CS, 1),
            0x36 => (SS, 1),
            0x3e => (DS, 1),
            _ => (DS, 0),
        };
        enum Op {
            Int(u8),
            Service(u8),
            Iret,
            Near(u16),
            Far(u16, u16),
            NearAt(u16),
            FarAt(u16),
        }
        let (op, len) = match (at(p), at(p + 1)) {
            (0xcd, n) if p == 0 => (Op::Int(n), 2),
            (0xfe, 0x38) if p == 0 && stub => (Op::Service(at(2)), 3),
            (0xcf, _) if p == 0 && stub => (Op::Iret, 1),
            (0xe8, _) if p == 0 => (Op::Near(ip.wrapping_add(3).wrapping_add(word(1))), 3),
            (0x9a, _) if p == 0 => (Op::Far(word(1), word(3)), 5),
            (0xff, 0x16) => (Op::NearAt(word(p + 2)), p + 4),
            (0xff, 0x1e) => (Op::FarAt(word(p + 2)), p + 4),
            _ => return None,
        };
        let c = &mut self.cpu;
        c.irq_inhibit = false;
        c.insn_cs = cs;
        c.insn_ip = ip;
        c.instructions += 1;
        let next = ip.wrapping_add(len);
        c.ip = next;
        let h = &mut self.hw;
        let step = match op {
            Op::Int(n) => {
                c.interrupt(h, n);
                Step::Ok
            }
            Op::Service(n) => Step::Callback(n),
            Op::Iret => {
                c.ip = c.pop(h);
                c.sregs[CS] = c.pop(h);
                let f = c.pop(h);
                c.set_flags(f);
                Step::Ok
            }
            Op::Near(t) => {
                c.push(h, next);
                c.ip = t;
                Step::Ok
            }
            Op::NearAt(a) => {
                let t = c.read16(h, seg, a);
                c.push(h, next);
                c.ip = t;
                Step::Ok
            }
            Op::Far(o, s) => {
                c.push(h, cs);
                c.push(h, next);
                (c.ip, c.sregs[CS]) = (o, s);
                Step::Ok
            }
            Op::FarAt(a) => {
                let o = c.read16(h, seg, a);
                let s = c.read16(h, seg, a.wrapping_add(2));
                c.push(h, cs);
                c.push(h, next);
                (c.ip, c.sregs[CS]) = (o, s);
                Step::Ok
            }
        };
        self.rec.as_mut().unwrap().host_steps += 1;
        if self.cpu.sregs[CS] != cs {
            self.rec_driver_called(self.cpu.sregs[CS]);
        }
        Some(step)
    }

    fn step_raw(&mut self) -> Result<(), Bail> {
        let replay = self.hw.io_log.replay.is_some();
        self.hw.now_ns = self.now_ns();
        match self.cpu_step() {
            Step::Ok => Ok(()),
            Step::Callback(n) => {
                self.service(n);
                Ok(())
            }
            Step::Halt if replay && matches!(self.hw.io_log.peek(), Some(IoEvent::Irq { .. })) => Ok(()),
            Step::Halt | Step::Invalid { .. } => Err(Bail),
        }
    }

    /// For generated code: the instruction at `ip` (seg000) is one the
    /// routine does not run natively (`INT`, far call, unknown target).
    /// Under shadow checking it is interpreted until execution is back at
    /// `next` with the same stack pointer; otherwise the routine bails with
    /// CS:IP on that instruction.
    pub fn rec_interp(&mut self, ip: u16, next: u16) -> Result<(), Bail> {
        self.cpu.ip = ip;
        self.rec_settle()?;
        let nested = self.rec.as_ref().is_some_and(|r| r.interp_nested);
        let (cs, ss, sp) = (self.cpu.sregs[CS], self.cpu.sregs[SS], self.cpu.regs[SP]);
        let back = |c: &Cpu| c.sregs[CS] == cs && c.ip == next && c.sregs[SS] == ss && c.regs[SP] == sp;
        if nested {
            self.step_insn()?;
            return self.interp_until(budget(), back);
        }
        // The graphics model check watches every instruction: leave these to
        // the run loop then. (Music driver calls are tracked here as there.)
        if self.gfx.active() {
            return Err(Bail);
        }
        // Running: BIOS/DOS services and driver calls are short; interpret
        // them here. One that takes long (it waits for an interrupt) is left
        // to the run loop, mid-way. After a service that showed the program
        // idle, the run loop must sleep: bail there too.
        let mut just_bailed = false;
        let first = self.cpu.instructions;
        for _ in 0..ON_INTERP_BUDGET {
            if self.music.watch[0] != 0 {
                let pc = self.cpu.phys(self.cpu.sregs[CS], self.cpu.ip);
                if let Some(entry) = self.music.hit(pc, self.cpu.instructions) {
                    self.on_music_call(entry);
                }
            }
            // Lifted code, natively, from any of its block leaders: a
            // driver's, or seg000's once the instruction itself has run.
            let here = self.cpu.sregs[CS];
            if (here != LOAD_SEG || self.cpu.instructions != first)
                && !just_bailed
                && let Some(g) = self.rec_routine(here, self.cpu.ip, false)
            {
                let at = self.cpu.ip;
                self.rec.as_mut().unwrap().calls += 1;
                just_bailed = g(self, at).is_err();
                if just_bailed {
                    self.rec.as_mut().unwrap().bails += 1;
                }
                if back(&self.cpu) {
                    return Ok(());
                }
                if self.exited.is_some() || self.rec_tick(1) {
                    return Err(Bail);
                }
                continue;
            }
            just_bailed = false;
            self.hw.now_ns = self.now_ns();
            let step = match self.host_step() {
                Some(s) => s,
                None => {
                    let (cs, ip, n0) = (self.cpu.sregs[CS], self.cpu.ip, self.cpu.instructions);
                    let s = self.cpu_step();
                    self.rec.as_mut().unwrap().count_interp(cs, ip, self.cpu.instructions - n0);
                    s
                }
            };
            match step {
                Step::Ok => {}
                Step::Callback(n) => {
                    self.service(n);
                    if self.idle_check() {
                        return Err(Bail);
                    }
                }
                Step::Halt | Step::Invalid { .. } => return Err(Bail),
            }
            if back(&self.cpu) {
                return Ok(());
            }
            // An interrupt or device event due: the run loop takes it now,
            // as it would have between these instructions.
            if self.exited.is_some() || self.rec_tick(1) {
                return Err(Bail);
            }
        }
        Err(Bail)
    }

    /// For generated code: call the routine at seg000 `target` with the
    /// return address `ret` already pushed. Uses its Rust version when there
    /// is one, else interprets it (shadow checking) or bails. On `Ok`, the
    /// callee has returned to `ret`.
    pub fn rec_call(&mut self, target: u16, ret: u16) -> Result<(), Bail> {
        self.cpu.ip = target;
        let nested = self.rec.as_ref().is_some_and(|r| r.interp_nested);
        let (cs, ss, sp) = (self.cpu.sregs[CS], self.cpu.sregs[SS], self.cpu.regs[SP]);
        self.rec_settle()?;
        if let Some(f) = self.rec_routine(cs, target, true) {
            let r = f(self, target);
            let r = self.rec_settle().and(r);
            match r {
                Ok(()) => {
                    let k = key(self.rec_space(cs).unwrap_or(0), target);
                    if let Some(r) = self.rec.as_mut() {
                        r.returned[k as usize] += 1;
                    }
                }
                // Shadow replay: the callee bailed (an interrupt due inside
                // it, a wait for one, code it does not run): finish it here
                // and carry on in the caller's Rust code.
                Err(Bail) if nested => self.finish_call(cs, ret, ss, sp)?,
                Err(e) => return Err(e),
            }
        } else if nested {
            self.finish_call(cs, ret, ss, sp)?;
        } else {
            return Err(Bail);
        }
        if self.cpu.ip == ret && self.cpu.sregs[CS] == cs { Ok(()) } else { Err(Bail) }
    }

    /// For readable ports, at the start of a stretch of `len` instructions
    /// from CS:IP (already set): true when the port must bail there, as
    /// [`Machine::rec_tick`]. First settles a stretch run through an
    /// interrupt before ([`Machine::rec_settle`]); on `Err` the port bails
    /// with the state the interpreter left.
    ///
    /// With `through` (a stretch without port I/O), in a shadow replay, a
    /// recorded interrupt due inside the stretch does not make it bail: the
    /// port runs the stretch without it, and at the next boundary the
    /// stretch is checked and the interrupt put in (see `rec_settle`). A
    /// port whose own loops always meet an interrupt is then still run to
    /// its end in Rust.
    pub fn rec_stretch(&mut self, len: u32, through: bool) -> Result<bool, Bail> {
        self.rec_settle()?;
        if self.hw.io_log.replay.is_none() || !through || self.rec.as_ref().is_some_and(|r| r.no_through) {
            return Ok(self.rec_tick(len));
        }
        let end = self.cpu.instructions + len as u64;
        self.hw.io_log.stopped = self.hw.io_log.stop_at < end;
        if self.hw.io_log.stopped {
            return Ok(true);
        }
        let due = matches!(self.hw.io_log.peek(), Some(&IoEvent::Irq { at, .. }) if at < end);
        if due && self.hw.io_log.mismatch.is_none() {
            let d = Deferred { cpu: self.cpu.clone(), mem: self.hw.mem.clone(), log: self.hw.io_log.replay };
            let rec = self.rec.as_mut().unwrap();
            rec.defer = Some(d);
            rec.deferred += 1;
        }
        Ok(false)
    }

    /// Shadow replay, at a port's boundary after a stretch it ran through an
    /// interrupt (CS:IP set to where the original is then): the stretch is
    /// interpreted from its start twice. Without the interrupts, it must
    /// give exactly the port's state (else the replay fails: the port
    /// differs). With them, delivered at their instruction, it gives the
    /// original's state, which the port goes on from. If the interrupts
    /// changed registers, flags or where the stretch ended (the port's
    /// locals may hold what the rest of it computed), the port bails there
    /// instead (the call counts as bailed).
    pub fn rec_settle(&mut self) -> Result<(), Bail> {
        let Some(rec) = self.rec.as_mut() else { return Ok(()) };
        let Some(d) = rec.defer.take() else { return Ok(()) };
        let now = self.cpu.instructions;
        let start = d.cpu.instructions;
        let at = d.cpu.ip;
        // Without the interrupts.
        let r_cpu = std::mem::replace(&mut self.cpu, d.cpu.clone());
        let r_mem = std::mem::replace(&mut self.hw.mem, d.mem.clone());
        let r_log = std::mem::replace(&mut self.hw.io_log.replay, d.log);
        let mut ok = now >= start;
        while ok && self.cpu.instructions < now {
            let n = self.cpu.instructions;
            ok = self.step_raw().is_ok() && self.hw.io_log.mismatch.is_none() && self.cpu.instructions > n;
        }
        // The result flags don't count here: past the stretch the port goes
        // on from the original's state (flags included), and flags a callee
        // or the port reads would differ in the calls without an interrupt,
        // which the end compare checks. (Readable ports leave flags no one
        // reads unset.)
        let pure = if ok {
            let mut stretch = self.cpu.clone();
            stretch.set_flags(stretch.flags() & !FLAG_BITS | r_cpu.flags() & FLAG_BITS);
            compare(&stretch, &self.hw.mem, &r_cpu, &r_mem)
        } else {
            None
        };
        let pure_log = self.hw.io_log.replay;
        let p_cpu = self.cpu.clone();
        self.hw.io_log.mismatch = None;
        if !ok {
            // Not interpretable on its own (port I/O after the interrupt):
            // the port's state can't be checked.
            self.hw.io_log.fail(format!("stretch from {at:04x} through an interrupt: not replayable without it"));
        } else if let Some(diff) = pure {
            self.hw.io_log.fail(format!("stretch from {at:04x} differs: {diff}"));
        } else if pure_log != r_log {
            self.hw.io_log.fail(format!("stretch from {at:04x} did different I/O"));
        }
        if self.hw.io_log.mismatch.is_some() {
            self.cpu = r_cpu;
            self.hw.mem = r_mem;
            self.hw.io_log.replay = r_log;
            return Err(Bail);
        }
        // With them: the original.
        self.cpu = d.cpu;
        self.hw.mem = d.mem;
        self.hw.io_log.replay = d.log;
        let pure_n = now - start;
        let mut own = 0u64;
        let mut frames: Vec<(u16, u16, u16, u16)> = Vec::new();
        while own < pure_n || !frames.is_empty() {
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > budget() {
                return Err(Bail);
            }
            // The original's call ended inside the stretch (it left its
            // frame some other way than its `ret`): the replay ends here.
            if self.cpu.instructions >= self.hw.io_log.stop_at {
                self.hw.io_log.stopped = true;
                return Err(Bail);
            }
            let c = &self.cpu;
            let frame = (c.sregs[CS], c.ip, c.sregs[SS], c.regs[SP]);
            if self.replay_irq() {
                frames.push(frame);
                continue;
            }
            let inside = !frames.is_empty();
            let n = self.cpu.instructions;
            self.step_raw()?;
            // The handlers' instructions are interpreted; the stretch's own
            // ones were run by the port.
            if inside {
                self.rec.as_mut().unwrap().replay_interp += self.cpu.instructions - n;
            } else {
                own += self.cpu.instructions - n;
            }
            let c = &self.cpu;
            let here = (c.sregs[CS], c.ip, c.sregs[SS], c.regs[SP]);
            while frames.last() == Some(&here) {
                frames.pop();
            }
        }
        let c = &self.cpu;
        let same = c.ip == p_cpu.ip && c.regs == p_cpu.regs && c.sregs == p_cpu.sregs && c.flags() == p_cpu.flags();
        if same {
            Ok(())
        } else {
            let rec = self.rec.as_mut().unwrap();
            rec.deferred_bailed += 1;
            rec.nested_bails += 1;
            Err(Bail)
        }
    }

    /// Shadow replay: run until the call whose return address `ret` was
    /// pushed at SS:SP returns there, the way [`Machine::replay_drive`]
    /// runs a check: recorded interrupts delivered at their instruction,
    /// Rust resumed at every block leader, the interpreter elsewhere. Bails
    /// at the end of the original's call (or on an I/O mismatch), which the
    /// replay then ends with.
    fn finish_call(&mut self, cs: u16, ret: u16, ss: u16, sp: u16) -> Result<(), Bail> {
        let start = self.cpu.instructions;
        let mut just_bailed = true;
        self.rec.as_mut().unwrap().nested_bails += 1;
        loop {
            let c = &self.cpu;
            if c.sregs[CS] == cs && c.ip == ret && c.sregs[SS] == ss && c.regs[SP] > sp {
                return Ok(());
            }
            if self.hw.io_log.replay.is_some() && self.cpu.instructions >= self.hw.io_log.stop_at {
                return Err(Bail);
            }
            if self.hw.io_log.mismatch.is_some() || self.cpu.instructions - start > budget() {
                return Err(Bail);
            }
            if self.replay_irq() {
                just_bailed = false;
                continue;
            }
            let ip = self.cpu.ip;
            let resume = if just_bailed { None } else { self.rec_routine(self.cpu.sregs[CS], ip, false) };
            if let Some(g) = resume {
                self.hw.io_log.stopped = false;
                let r = g(self, ip);
                just_bailed = self.rec_settle().and(r).is_err();
                if just_bailed {
                    self.rec.as_mut().unwrap().nested_bails += 1;
                }
            } else {
                just_bailed = false;
                self.step_insn()?;
            }
        }
    }
}

/// Bytes of a ModRM operand (ModRM, displacement), 16-bit addressing.
fn modrm_len(modrm: u8) -> u16 {
    match (modrm >> 6, modrm & 7) {
        (0, 6) => 3,
        (0, _) | (3, _) => 1,
        (1, _) => 2,
        _ => 3,
    }
}

/// First register difference between two CPU states, if any.
/// CF, PF, AF, ZF, SF and OF: the flags results set.
const FLAG_BITS: u16 = 0x8d5;

fn compare_cpu(c1: &Cpu, c2: &Cpu) -> Option<String> {
    for (i, (a, b)) in c1.regs.iter().zip(&c2.regs).enumerate() {
        if a != b {
            return Some(format!("reg {} {a:04x} vs {b:04x}", ["AX", "CX", "DX", "BX", "SP", "BP", "SI", "DI"][i]));
        }
    }
    for (i, (a, b)) in c1.sregs.iter().zip(&c2.sregs).enumerate() {
        if a != b {
            return Some(format!("sreg {} {a:04x} vs {b:04x}", ["ES", "CS", "SS", "DS"][i]));
        }
    }
    if c1.ip != c2.ip {
        return Some(format!("ip {:04x} vs {:04x}", c1.ip, c2.ip));
    }
    // Flags the 286 leaves undefined after some instructions are compared
    // too: the interpreter's values are the reference.
    if c1.flags() != c2.flags() {
        return Some(format!("flags {:04x} vs {:04x}", c1.flags(), c2.flags()));
    }
    None
}

/// First difference between two machine states, if any.
fn compare(c1: &Cpu, m1: &[u8], c2: &Cpu, m2: &[u8]) -> Option<String> {
    if let Some(d) = compare_cpu(c1, c2) {
        return Some(d);
    }
    let dead = dead_stack(c1);
    if m1 != m2 {
        let i = m1.iter().zip(m2).enumerate().position(|(i, (a, b))| a != b && !dead.contains(&i));
        if let Some(i) = i {
            return Some(format!("mem {:05x}: {:02x} vs {:02x}", i, m1[i], m2[i]));
        }
    }
    None
}

/// The game's stack: set to 3CBCh at the start (F087h); the data the code
/// addresses ends at 39B9h.
const STACK_LOW: u16 = 0x39c0;
const STACK_TOP: u16 = 0x3cbc;

/// The dead part of the game's stack (linear addresses): below SP, down
/// to [`STACK_LOW`]; empty when SP is not in the stack. Its contents are
/// not state: an interrupt taken where a readable port stops pushes that
/// port's flags there (they are not kept exact where no one reads them),
/// and nothing reads below SP. Any effect such a word could have would
/// show in the live state. Left out of the shadow compare and the state
/// hash.
pub fn dead_stack(cpu: &Cpu) -> std::ops::Range<usize> {
    let sp = cpu.regs[SP];
    if !(STACK_LOW..=STACK_TOP).contains(&sp) {
        return 0..0;
    }
    let ss = (cpu.sregs[SS] as usize) << 4;
    ss + STACK_LOW as usize..ss + sp as usize
}

